use crate::hpke::HpkeKey;
use crate::ssl::ech::SslEchKeys;
use crate::ssl::test::server::{ClientSslBuilder, Server};
use crate::ssl::{
    BoxSelectCertActionFinish, ClientHello, EchPolicy, HandshakeError, NameType, SelectCertAction,
    SelectCertError, Ssl, SslContextBuilder, SslMethod, SslVersion,
};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::task::Waker;

// For future reference, these configs are generated by building the bssl tool (the binary is built
// alongside boringssl) and running the following command:
//
// ./bssl generate-ech -out-ech-config-list ./list -out-ech-config ./config -out-private-key ./key
// -public-name ech.com -config-id 1
static ECH_CONFIG_LIST: &[u8] = include_bytes!("../../../test/echconfiglist");
static ECH_CONFIG: &[u8] = include_bytes!("../../../test/echconfig");
static ECH_KEY: &[u8] = include_bytes!("../../../test/echkey");

static ECH_CONFIG_2: &[u8] = include_bytes!("../../../test/echconfig-2");
static ECH_KEY_2: &[u8] = include_bytes!("../../../test/echkey-2");

fn bootstrap_ech(config: &[u8], key: &[u8], list: Option<&[u8]>) -> (Server, ClientSslBuilder) {
    let server = {
        let key = HpkeKey::dhkem_p256_sha256(key).unwrap();
        let mut ech_keys_builder = SslEchKeys::builder().unwrap();
        ech_keys_builder.add_key(true, config, key).unwrap();
        let ech_keys = ech_keys_builder.build();

        let mut builder = Server::builder();
        builder.ctx().set_ech_keys(&ech_keys).unwrap();

        builder.build()
    };

    let mut client = server.client_with_root_ca().build().builder();
    if let Some(list) = list {
        client.ssl().set_ech_config_list(list).unwrap();
    }
    client.ssl().set_hostname("foobar.com").unwrap();

    (server, client)
}

#[test]
fn ech() {
    let (_server, client) = bootstrap_ech(ECH_CONFIG, ECH_KEY, Some(ECH_CONFIG_LIST));

    let ssl_stream = client.connect();
    assert!(ssl_stream.ssl().ech_accepted());
}

fn unsupported_ech_config_list() -> Vec<u8> {
    let mut list = ECH_CONFIG_LIST.to_vec();
    // The first two bytes are the list length; use an unknown ECHConfig version.
    list[2..4].copy_from_slice(&0xffffu16.to_be_bytes());
    list
}

fn new_ech_policy_client_ssl() -> Ssl {
    let ctx = SslContextBuilder::new(SslMethod::tls()).unwrap().build();
    Ssl::new(&ctx).unwrap()
}

fn assert_ech_policy_fails_before_client_hello(ssl: Ssl) {
    let wire = std::io::Cursor::new(Vec::<u8>::new());
    let HandshakeError::Failure(failed) = ssl.connect(wire).unwrap_err() else {
        panic!("expected handshake failure");
    };
    let errors = failed.error().ssl_error().unwrap();
    assert!(errors.errors().iter().any(|err| {
        err.library_reason(crate::ffi::ERR_LIB_SSL)
            == Some(crate::ffi::SSL_R_UNUSABLE_ECH_CONFIG_LIST)
    }));
    assert!(failed.get_ref().get_ref().is_empty());
}

#[test]
fn ech_config_policy_required_rejects_unsupported_list_before_client_hello() {
    let mut ssl = new_ech_policy_client_ssl();
    ssl.set_enable_ech_grease(true);
    ssl.set_ech_config_list_with_policy(&unsupported_ech_config_list(), EchPolicy::Required)
        .unwrap();

    assert_ech_policy_fails_before_client_hello(ssl);
}

#[test]
fn ech_config_policy_required_rejects_tls_1_2_before_client_hello() {
    let mut ssl = new_ech_policy_client_ssl();
    ssl.set_max_proto_version(Some(SslVersion::TLS1_2)).unwrap();
    ssl.set_ech_config_list_with_policy(ECH_CONFIG_LIST, EchPolicy::Required)
        .unwrap();

    assert_ech_policy_fails_before_client_hello(ssl);
}

#[test]
fn ech_config_policy_opportunistic_allows_unsupported_list() {
    let list = unsupported_ech_config_list();
    let (_server, client) = bootstrap_ech(ECH_CONFIG, ECH_KEY, Some(&list));
    assert!(!client.connect().ssl().ech_accepted());

    let (_server, mut client) = bootstrap_ech(ECH_CONFIG, ECH_KEY, None);
    client
        .ssl()
        .set_ech_config_list_with_policy(&list, EchPolicy::Required)
        .unwrap();
    client
        .ssl()
        .set_ech_config_list_with_policy(&list, EchPolicy::Opportunistic)
        .unwrap();
    assert!(!client.connect().ssl().ech_accepted());
}

#[test]
fn ech_config_policy_required_accepts_valid_config() {
    let (_server, mut client) = bootstrap_ech(ECH_CONFIG, ECH_KEY, None);
    client
        .ssl()
        .set_ech_config_list_with_policy(ECH_CONFIG_LIST, EchPolicy::Required)
        .unwrap();

    assert!(client.connect().ssl().ech_accepted());
}

#[test]
fn ech_config_policy_malformed_list_preserves_required_policy() {
    let mut ssl = new_ech_policy_client_ssl();
    ssl.set_ech_config_list_with_policy(&unsupported_ech_config_list(), EchPolicy::Required)
        .unwrap();

    assert!(ssl
        .set_ech_config_list_with_policy(&[], EchPolicy::Opportunistic)
        .is_err());
    assert_ech_policy_fails_before_client_hello(ssl);
}

#[test]
fn ech_disable_from_select_certificate_callback() {
    let calls = Arc::new(AtomicUsize::new(0));
    let observations = Arc::new(Mutex::new(Vec::new()));
    let server = {
        let key = HpkeKey::dhkem_p256_sha256(ECH_KEY).unwrap();
        let mut ech_keys_builder = SslEchKeys::builder().unwrap();
        ech_keys_builder.add_key(true, ECH_CONFIG, key).unwrap();
        let ech_keys = ech_keys_builder.build();

        let mut builder = Server::builder();
        builder.ctx().set_ech_keys(&ech_keys).unwrap();
        let calls = calls.clone();
        let observations = observations.clone();
        builder
            .ctx()
            .set_select_certificate_callback_with_action(move |client_hello| {
                calls.fetch_add(1, Ordering::Relaxed);
                observations.lock().unwrap().push((
                    client_hello.ssl().ech_accepted(),
                    client_hello
                        .ssl()
                        .servername(NameType::HOST_NAME)
                        .map(str::to_owned),
                ));
                if client_hello.ssl().ech_accepted() {
                    Ok(SelectCertAction::DisableEch)
                } else {
                    Ok(SelectCertAction::Success)
                }
            });

        builder.build()
    };

    let mut client = server.client_with_root_ca().build().builder();
    client.ssl().set_ech_config_list(ECH_CONFIG_LIST).unwrap();
    client.ssl().set_hostname("foobar.com").unwrap();
    let HandshakeError::Failure(failed_ssl_stream) = client.connect_err() else {
        panic!("wrong HandshakeError failure variant!");
    };

    assert!(!failed_ssl_stream.ssl().ech_accepted());
    assert!(failed_ssl_stream.ssl().get_ech_retry_configs().is_none());
    assert_eq!(calls.load(Ordering::Relaxed), 2);
    assert_eq!(
        *observations.lock().unwrap(),
        vec![
            (true, Some("foobar.com".to_owned())),
            (false, Some("ech.com".to_owned())),
        ]
    );
}

#[test]
fn ech_disable_repeatedly_fails_after_outer_client_hello() {
    let calls = Arc::new(AtomicUsize::new(0));
    let server = {
        let key = HpkeKey::dhkem_p256_sha256(ECH_KEY).unwrap();
        let mut ech_keys_builder = SslEchKeys::builder().unwrap();
        ech_keys_builder.add_key(true, ECH_CONFIG, key).unwrap();
        let ech_keys = ech_keys_builder.build();

        let mut builder = Server::builder();
        builder.should_error();
        builder.ctx().set_ech_keys(&ech_keys).unwrap();
        let calls = calls.clone();
        builder
            .ctx()
            .set_select_certificate_callback_with_action(move |_client_hello| {
                if calls.fetch_add(1, Ordering::Relaxed) < 2 {
                    Ok(SelectCertAction::DisableEch)
                } else {
                    Err(SelectCertError::ERROR)
                }
            });

        builder.build()
    };

    let mut client = server.client_with_root_ca().build().builder();
    client.ssl().set_ech_config_list(ECH_CONFIG_LIST).unwrap();
    client.ssl().set_hostname("foobar.com").unwrap();
    client.connect_err();

    assert_eq!(calls.load(Ordering::Relaxed), 2);
}

#[test]
fn ech_disable_from_async_select_certificate_callback() {
    let calls = Arc::new(AtomicUsize::new(0));
    let server = {
        let key = HpkeKey::dhkem_p256_sha256(ECH_KEY).unwrap();
        let mut ech_keys_builder = SslEchKeys::builder().unwrap();
        ech_keys_builder.add_key(true, ECH_CONFIG, key).unwrap();
        let ech_keys = ech_keys_builder.build();

        let mut builder = Server::builder();
        builder.ctx().set_ech_keys(&ech_keys).unwrap();
        let calls = calls.clone();
        builder
            .ctx()
            .set_async_select_certificate_callback_with_action(move |_| {
                let calls = calls.clone();
                Ok(Box::pin(async move {
                    Ok(Box::new(move |_client_hello: ClientHello<'_>| {
                        if calls.fetch_add(1, Ordering::Relaxed) == 0 {
                            Ok(SelectCertAction::DisableEch)
                        } else {
                            Ok(SelectCertAction::Success)
                        }
                    }) as BoxSelectCertActionFinish)
                }))
            });
        builder.ssl_cb(|ssl| ssl.set_task_waker(Some(Waker::noop().clone())));

        builder.build()
    };

    let mut client = server.client_with_root_ca().build().builder();
    client.ssl().set_ech_config_list(ECH_CONFIG_LIST).unwrap();
    client.ssl().set_hostname("foobar.com").unwrap();
    let HandshakeError::Failure(failed_ssl_stream) = client.connect_err() else {
        panic!("wrong HandshakeError failure variant!");
    };

    assert!(!failed_ssl_stream.ssl().ech_accepted());
    assert!(failed_ssl_stream.ssl().get_ech_retry_configs().is_none());
    assert_eq!(calls.load(Ordering::Relaxed), 2);
}

#[test]
fn ech_rejection() {
    // Server is initialized using `ECH_CONFIG_2`, so using `ECH_CONFIG_LIST` instead of
    // `ECH_CONFIG_LIST_2` should trigger rejection.
    let (_server, client) = bootstrap_ech(ECH_CONFIG_2, ECH_KEY_2, Some(ECH_CONFIG_LIST));

    let HandshakeError::Failure(failed_ssl_stream) = client.connect_err() else {
        panic!("wrong HandshakeError failure variant!");
    };
    assert_eq!(
        failed_ssl_stream.ssl().get_ech_name_override(),
        Some(b"ech.com".to_vec().as_ref())
    );
    assert!(failed_ssl_stream.ssl().get_ech_retry_configs().is_some());
    assert!(!failed_ssl_stream.ssl().ech_accepted());
}

#[test]
fn ech_grease() {
    let server = Server::builder().build();

    let mut client = server.client_with_root_ca().build().builder();
    // Verified with a pcap locally that the ECH extension gets sent due to GREASE
    client.ssl().set_enable_ech_grease(true);

    let ssl_stream = client.connect();
    assert!(!ssl_stream.ssl().ech_accepted());
}

// An ECH server answers GREASE with retry configs in EncryptedExtensions, which
// the client only accepts when its rotated GREASE extension counts as sent.
#[cfg(not(feature = "fips"))]
#[test]
fn ech_grease_policy_accepts_retry_configs() {
    use std::sync::atomic::{AtomicUsize, Ordering};
    use std::sync::Arc;

    let (_server, mut client) = bootstrap_ech(ECH_CONFIG, ECH_KEY, None);
    client.ssl().set_enable_ech_grease(true);
    let calls = Arc::new(AtomicUsize::new(0));
    let count = Arc::clone(&calls);
    client
        .ssl()
        .set_ech_grease_callback(move |_, info| {
            count.fetch_add(1, Ordering::SeqCst);
            Ok(crate::ssl::EchGreaseParameters {
                aead: info.default_aead(),
                payload_length: std::num::NonZeroU16::new(239).unwrap(),
                random_enc: true,
            })
        })
        .unwrap();
    let stream = client.connect();
    assert!(!stream.ssl().ech_accepted());
    assert_eq!(calls.load(Ordering::SeqCst), 1);
}

#[cfg(not(feature = "fips"))]
#[test]
fn ech_real_configuration_bypasses_custom_grease_policy() {
    let (_server, mut client) = bootstrap_ech(ECH_CONFIG, ECH_KEY, Some(ECH_CONFIG_LIST));
    client.ssl().set_enable_ech_grease(true);
    client
        .ssl()
        .set_ech_grease_callback(|_, _| panic!("real ECH used GREASE policy"))
        .unwrap();
    assert!(client.connect().ssl().ech_accepted());
}

#[cfg(not(feature = "fips"))]
#[test]
fn ech_rejection_does_not_invoke_custom_grease_policy() {
    let (_server, mut client) = bootstrap_ech(ECH_CONFIG_2, ECH_KEY_2, Some(ECH_CONFIG_LIST));
    client.ssl().set_enable_ech_grease(true);
    client
        .ssl()
        .set_ech_grease_callback(|_, _| panic!("rejected real ECH used GREASE policy"))
        .unwrap();
    let HandshakeError::Failure(failed) = client.connect_err() else {
        panic!("expected ECH rejection");
    };
    assert!(failed.ssl().get_ech_retry_configs().is_some());
    assert!(!failed.ssl().ech_accepted());
}

#[cfg(not(feature = "fips"))]
#[test]
fn ech_inner_encoding_preserves_default_and_accepts_nss() {
    use crate::ssl::{EchInnerEncoding, ExtensionType, SslVersion};

    fn extension_ids(mut hello: &[u8], cipher_len: usize) -> Vec<u16> {
        // Legacy version, random, then the variable-length legacy session ID.
        hello = &hello[34..];
        hello = &hello[1 + usize::from(hello[0])..];
        hello = &hello[2 + cipher_len..];
        hello = &hello[1 + usize::from(hello[0])..];
        assert_eq!(
            usize::from(u16::from_be_bytes([hello[0], hello[1]])),
            hello.len() - 2
        );
        hello = &hello[2..];
        let mut ids = Vec::new();
        while !hello.is_empty() {
            ids.push(u16::from_be_bytes([hello[0], hello[1]]));
            let len = usize::from(u16::from_be_bytes([hello[2], hello[3]]));
            hello = &hello[4 + len..];
        }
        ids
    }

    for encoding in [
        None,
        Some(EchInnerEncoding::Default),
        Some(EchInnerEncoding::Nss),
    ] {
        let key = HpkeKey::dhkem_p256_sha256(ECH_KEY).unwrap();
        let mut keys = SslEchKeys::builder().unwrap();
        keys.add_key(true, ECH_CONFIG, key).unwrap();
        let mut server = Server::builder();
        server.ctx().set_ech_keys(&keys.build()).unwrap();
        server.ctx().set_record_size_limit(1_024);
        let observed = Arc::new(Mutex::new(None));
        let captured = Arc::clone(&observed);
        server.ctx().set_select_certificate_callback(move |hello| {
            let ciphers = hello.ciphers();
            *captured.lock().unwrap() = Some((
                hello.ssl().ech_accepted(),
                ciphers.to_vec(),
                extension_ids(hello.as_bytes(), ciphers.len()),
                hello
                    .get_extension(ExtensionType::RECORD_SIZE_LIMIT)
                    .unwrap()
                    .to_vec(),
            ));
            Ok(())
        });
        let server = server.build();

        let mut client = server.client_with_root_ca();
        let ctx = client.ctx();
        ctx.set_min_proto_version(Some(SslVersion::TLS1_2)).unwrap();
        ctx.set_cipher_list("ECDHE-RSA-AES128-GCM-SHA256").unwrap();
        ctx.set_record_size_limit(1_024);
        ctx.set_extension_permutation(&[
            ExtensionType::SERVER_NAME,
            ExtensionType::RECORD_SIZE_LIMIT,
            ExtensionType::ENCRYPTED_CLIENT_HELLO,
            ExtensionType::SUPPORTED_VERSIONS,
        ])
        .unwrap();
        if let Some(encoding) = encoding {
            ctx.set_ech_inner_encoding(encoding);
        }
        let mut client = client.build().builder();
        client.ssl().set_ech_config_list(ECH_CONFIG_LIST).unwrap();
        client.ssl().set_hostname("foobar.com").unwrap();
        let stream = client.connect();
        assert!(stream.ssl().ech_accepted());
        assert_eq!(stream.ssl().version_str(), "TLSv1.3");

        let (accepted, ciphers, ids, limit) = observed.lock().unwrap().take().unwrap();
        assert!(accepted);
        assert_eq!(limit, 1_024u16.to_be_bytes());
        let nss = encoding == Some(EchInnerEncoding::Nss);
        assert_eq!(
            ids[0] == ExtensionType::ENCRYPTED_CLIENT_HELLO.as_raw(),
            nss
        );
        assert_eq!(ciphers.chunks_exact(2).any(|id| id == [0xc0, 0x2f]), nss);
        let limit_pos = ids
            .iter()
            .position(|id| *id == ExtensionType::RECORD_SIZE_LIMIT.as_raw())
            .unwrap();
        let versions_pos = ids
            .iter()
            .position(|id| *id == ExtensionType::SUPPORTED_VERSIONS.as_raw())
            .unwrap();
        assert_eq!(limit_pos > versions_pos, nss);
    }
}

#[cfg(not(feature = "fips"))]
#[test]
fn ech_nss_encoding_across_hrr_and_resumption() {
    use crate::ssl::{EchInnerEncoding, KeyShare, SslSessionCacheMode};

    let key = HpkeKey::dhkem_p256_sha256(ECH_KEY).unwrap();
    let mut keys = SslEchKeys::builder().unwrap();
    keys.add_key(true, ECH_CONFIG, key).unwrap();
    let mut server = Server::builder();
    server.expected_connections_count(2);
    server.ctx().set_ech_keys(&keys.build()).unwrap();
    server.ctx().set_curves_list("P-384").unwrap();
    let server = server.build();

    let mut client = server.client_with_root_ca();
    client.ctx().set_ech_inner_encoding(EchInnerEncoding::Nss);
    client.ctx().set_curves_list("X25519:P-384").unwrap();
    client
        .ctx()
        .set_session_cache_mode(SslSessionCacheMode::CLIENT);
    let session = Arc::new(Mutex::new(None));
    let saved = Arc::clone(&session);
    client.ctx().set_new_session_callback(move |_, ticket| {
        *saved.lock().unwrap() = Some(ticket);
    });
    let client = client.build();
    let configure = |client: &mut ClientSslBuilder| {
        client.ssl().set_ech_config_list(ECH_CONFIG_LIST).unwrap();
        client.ssl().set_hostname("foobar.com").unwrap();
    };

    let mut first = client.builder();
    configure(&mut first);
    first
        .ssl()
        .set_client_key_shares(&[KeyShare::X25519])
        .unwrap();
    let first = first.connect();
    assert!(first.ssl().used_hello_retry_request());
    assert!(first.ssl().ech_accepted());
    assert!(!first.ssl().session_reused());

    let session = session
        .lock()
        .unwrap()
        .take()
        .expect("server sent a ticket");
    let mut second = client.builder();
    configure(&mut second);
    second
        .ssl()
        .set_client_key_shares(&[KeyShare::P384])
        .unwrap();
    // This session was issued for the same origin and client context above.
    unsafe { second.ssl().set_session(&session).unwrap() };
    let resumed = second.connect();
    assert!(resumed.ssl().ech_accepted());
    assert!(resumed.ssl().session_reused());
}
